<template>
  <section v-page-loading="{ active: pageLoading, variant: reviewer ? 'list' : 'form', fields: 7 }" class="verification-panel" :class="{ 'reviewer-panel': reviewer && !embedded, 'reviewer-embedded': reviewer && embedded }">
    <p class="eyebrow">Business verification</p><h1>{{ reviewer ? 'Supplier Verification' : 'Verify your supplier business' }}</h1>
    <p>Complete business verification to unlock your supplier catalog and clinic orders. Your documents are reviewed by an administrator before any clinic transactions are available.</p>
    <ol v-if="!reviewer" class="onboarding-steps" aria-label="Supplier onboarding steps"><li class="current"><span>1</span><div><strong>Business verification</strong><small>Business details and documents</small></div></li><li :class="{ current: ['Submitted', 'Under review', 'Verified'].includes(application?.verificationStatus) }"><span>2</span><div><strong>Administrator review</strong><small>Document review and decision</small></div></li><li :class="{ current: application?.verificationStatus === 'Verified' }"><span>3</span><div><strong>Supplier portal</strong><small>Catalog and clinic orders</small></div></li></ol>
    <p v-if="error" role="alert" class="error">{{ error }} <button type="button" @click="load">Retry</button></p>
    <template v-if="reviewer">
      <nav class="review-tabs" aria-label="Supplier verification categories">
        <button v-for="tab in reviewTabs" :key="tab.id" type="button" :class="{ active: activeReviewTab === tab.id }" :aria-current="activeReviewTab === tab.id ? 'page' : undefined" @click="activeReviewTab = tab.id">{{ tab.label }} <span>({{ tab.count }})</span></button>
      </nav>
      <p v-if="!filtered.length && !error" class="empty-state">{{ emptyMessage }}</p>
      <article v-for="application in filtered" :key="application.id" class="card">
        <div class="row"><h2>{{ application.businessName || application.companyName || 'Supplier application' }}</h2><div><span class="badge">{{ application.verificationStatus }}</span><span v-if="application.ocrStatus" class="badge">{{ application.ocrStatus }}</span></div></div>
        <p>{{ application.contactEmail || application.email }} · {{ application.contactPhone }}</p><p>{{ application.businessAddress }}</p>
        <p>Registration: {{ application.registrationNumber || 'Not submitted' }} · Tax number: {{ application.taxNumber || 'Not submitted' }}</p><p>Representative: {{ application.representativeName }}</p>
        <div class="documents"><details v-for="(document, kind) in application.documents" :key="kind"><summary>{{ labels[kind] || kind }}: {{ document.name }} · {{ document.ocr?.status || 'OCR unavailable' }}<span v-if="document.ocr?.confidence != null"> · {{ Math.round(document.ocr.confidence * 100) }}%</span></summary><p>{{ document.ocr?.reason || 'No OCR assessment stored.' }}</p><p v-if="document.ocr?.checks?.expiryDate">Expiry: {{ document.ocr.checks.expiryDate }}<span v-if="document.ocr.checks.expiryDaysRemaining != null"> · {{ document.ocr.checks.expiryDaysRemaining }} days remaining</span></p><pre>{{ document.ocr?.extractedText || 'No text was extracted.' }}</pre><button type="button" @click="openDocument(application.id, kind)">Open original document</button></details></div>
        <p v-if="application.ocrReviewReason">OCR note: {{ application.ocrReviewReason }}</p><p v-if="application.revisionReason">Review reason: {{ application.revisionReason }}</p>
        <label v-if="['Submitted', 'Under review', 'Verified'].includes(application.verificationStatus)">Review reason<textarea v-model="reasons[application.id]" rows="2" maxlength="2000" placeholder="Explain requested changes, rejection, or suspension" /></label>
        <div class="actions" v-if="['Submitted', 'Under review'].includes(application.verificationStatus)"><button :disabled="busy" @click="review(application, 'approve')">Approve</button><button :disabled="busy" @click="review(application, 'revise')">Request revisions</button><button :disabled="busy" @click="review(application, 'reject')">Reject</button></div>
        <button v-if="application.verificationStatus === 'Verified'" :disabled="busy" @click="review(application, 'suspend')">Suspend supplier</button>
        <button type="button" @click="loadHistory(application.id)">View review history</button>
        <ol v-if="histories[application.id]"><li v-for="entry in histories[application.id]" :key="entry.id">{{ entry.previousStatus }} → {{ entry.nextStatus }} · {{ entry.reason || entry.action }} · {{ entry.actorId }}</li></ol>
      </article>
    </template>
    <template v-else-if="application">
      <div class="card"><span class="badge">{{ application.verificationStatus }}</span><span v-if="application.ocrStatus" class="badge">{{ application.ocrStatus }}</span><p v-if="application.revisionReason">{{ application.revisionReason }}</p><p v-if="application.verificationStatus === 'Verified'">Your supplier business is verified. Catalog and clinic order features are unlocked.</p><p v-else-if="['Submitted', 'Under review'].includes(application.verificationStatus)">Your documents are awaiting review. The supplier portal remains locked until approval. You can return here to see the decision.</p><p v-else-if="application.verificationStatus === 'Rejected'">Your application was rejected. Contact the administrator for more information or submit corrected details if resubmission is allowed.</p><RouterLink v-if="application.verificationStatus === 'Verified'" class="portal-link" to="/supplier/supplies">Continue to supplier portal</RouterLink></div>
      <form @submit.prevent="submit" class="card">
        <fieldset :disabled="locked || busy"><div class="onboarding-layout"><div class="input-column">
          <section class="form-section"><div class="section-heading"><div><p class="eyebrow">Business details</p><h2>Enter your information</h2></div></div><div class="fields"><label v-for="field in fields" :key="field.key">{{ field.label }}<input v-model.trim="form[field.key]" :type="field.type || 'text'" required maxlength="500" :placeholder="field.key === 'registrationNumber' || field.key === 'taxNumber' ? 'Auto-filled from uploaded documents when detected' : ''" /></label></div><div class="map-section"><p class="field-title">Business address and map location <span>*</span></p><p class="helper-text">Search for your address, then place the pin at your business location.</p><LocationPicker region="cavite" title="Select Business Location in Cavite" instruction-title="Cavite only" instruction-text="Pin the exact location of your business inside Cavite." search-placeholder="Search your business address in Cavite" search-hint="Search first, then fine-tune the exact spot by dragging or clicking the pin." allowed-area-label="Cavite, Philippines" pinned-address-label="Pinned Business Address" :show-actions="false" :initial-address="form.businessAddress" :initial-lat="form.businessAddressLat" :initial-lng="form.businessAddressLng" @selection-change="handleLocationSelection" @error="locationError = $event"/><p v-if="locationError" class="map-error">{{ locationError }}</p></div></section>
          <section class="form-section"><div class="section-heading"><div><p class="eyebrow">Required documents</p><h2>Upload verification files</h2></div><span class="upload-limit">One file per type · up to 10 MB</span></div><div class="upload-list"><label v-for="kind in Object.keys(labels)" :key="kind" class="upload-card" @click="selectedDocumentKind = kind"><span class="upload-label">{{ labels[kind] }} <small>{{ kind === 'distribution' ? 'Optional' : 'Required' }}</small></span><input type="file" accept="application/pdf,image/png,image/jpeg" @change="upload(kind, $event)" /><span class="file-name">{{ application.documents?.[kind]?.name || 'Choose a PDF, PNG, or JPEG' }}</span><small v-if="application.documents?.[kind]?.ocr" class="ocr-status">{{ application.documents[kind].ocr.status }} · {{ application.documents[kind].ocr.reason }}</small></label></div></section>
        </div><aside class="preview-column" aria-live="polite"><div class="preview-heading"><div><p class="eyebrow">Live preview</p><h2>Application information</h2></div><span class="badge">{{ application.verificationStatus || 'Draft' }}</span></div><div class="preview-group"><h3>Business</h3><dl><div><dt>Legal name</dt><dd>{{ form.businessName || 'Will appear here' }}</dd></div><div><dt>Registration number</dt><dd>{{ form.registrationNumber || 'Upload a registration document to detect' }}</dd></div><div><dt>Tax number</dt><dd>{{ form.taxNumber || 'Upload a permit or tax document to detect' }}</dd></div><div><dt>Address</dt><dd>{{ form.businessAddress || 'Select a location on the map' }}</dd></div><div v-if="form.businessAddressLat && form.businessAddressLng"><dt>Map coordinates</dt><dd>{{ form.businessAddressLat }}, {{ form.businessAddressLng }}</dd></div></dl></div><div class="preview-group"><h3>Representative and contact</h3><dl><div><dt>Representative</dt><dd>{{ form.representativeName || 'Will appear here' }}</dd></div><div><dt>Email</dt><dd>{{ form.contactEmail || 'Will appear here' }}</dd></div><div><dt>Phone</dt><dd>{{ form.contactPhone || 'Will appear here' }}</dd></div></dl></div><div class="preview-group"><h3>Document checks</h3><div v-for="kind in Object.keys(labels)" :key="kind" class="preview-document"><span>{{ labels[kind] }}</span><strong :class="selectedDocumentStatusClass(kind)">{{ selectedDocumentStatus(kind) }}</strong><small v-if="application.documents?.[kind]?.ocr?.checks?.expiryDate">Expires {{ application.documents[kind].ocr.checks.expiryDate }}</small></div></div><div class="ocr-preview"><div class="reader-heading"><div><p class="eyebrow">OCR extraction</p><h3>{{ labels[selectedDocumentKind] }}</h3></div><button v-if="application.documents?.[selectedDocumentKind]" type="button" @click="openDocument(application.id, selectedDocumentKind)">Open file</button></div><template v-if="selectedDocument?.ocr"><div class="ocr-summary"><span class="badge">{{ selectedDocument.ocr.status }}</span><strong>{{ Math.round(Number(selectedDocument.ocr.confidence || 0) * 100) }}%</strong></div><p>{{ selectedDocument.ocr.reason }}</p><p v-if="selectedDocument.ocr.extractedFields?.registrationNumber">Registration number detected: {{ selectedDocument.ocr.extractedFields.registrationNumber }}</p><p v-if="selectedDocument.ocr.extractedFields?.taxNumber">Tax number detected: {{ selectedDocument.ocr.extractedFields.taxNumber }}</p><pre class="extracted-text">{{ selectedDocument.ocr.extractedText || 'No text was extracted.' }}</pre></template><p v-else class="reader-empty">Upload a document to preview extracted text and validation results.</p></div></aside></div>
          <button type="submit" :disabled="busy">{{ busy ? 'Saving…' : 'Submit for verification' }}</button>
        </fieldset>
      </form>
    </template>
    <a v-if="documentUrl" class="document-link" :href="documentUrl" target="_blank" rel="noopener">Open selected document (link expires in 5 minutes)</a>
  </section>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { auth } from '@/config/firebaseConfig'
import { OTP_API_BASE } from '@/utils/runtimeConfig'
import { usePageLoading } from '@/composables/usePageLoading'
import { toast } from 'vue3-toastify'
import LocationPicker from '@/components/common/LocationPicker.vue'
const props = defineProps({ reviewer: Boolean, embedded: Boolean })
const { pageLoading, trackPageLoad } = usePageLoading()
const application = ref(null), applications = ref([]), form = ref({}), activeReviewTab = ref('ocr'), reasons = ref({}), histories = ref({}), error = ref(''), busy = ref(false), documentUrl = ref(''), selectedDocumentKind = ref('registration'), locationError = ref('')
const selectedDocument = computed(() => application.value?.documents?.[selectedDocumentKind.value] || null)
const labels = { registration: 'Business registration', permit: 'Business permit / tax document', representative: 'Representative authorization', distribution: 'Distribution credentials' }
const fields = [{ key: 'businessName', label: 'Legal business name' }, { key: 'registrationNumber', label: 'Business registration number' }, { key: 'taxNumber', label: 'Tax identification number' }, { key: 'representativeName', label: 'Authorized representative' }, { key: 'contactEmail', label: 'Contact email', type: 'email' }, { key: 'contactPhone', label: 'Contact phone', type: 'tel' }]
const locked = computed(() => ['Submitted', 'Under review', 'Verified', 'Suspended'].includes(application.value?.verificationStatus))
const getReviewCategory = a => {
  const status = String(a.verificationStatus || '').toLowerCase()
  if (status === 'verified') return 'approved'
  if (status === 'rejected') return 'rejected'
  if (!['submitted', 'under review'].includes(status)) return 'other'
  return String(a.ocrStatus || '').toLowerCase() === 'ocr verified' ? 'ocr' : 'manual'
}
const reviewTabs = computed(() => [
  { id: 'ocr', label: 'OCR-Verified', count: applications.value.filter(a => getReviewCategory(a) === 'ocr').length },
  { id: 'manual', label: 'Manual review', count: applications.value.filter(a => getReviewCategory(a) === 'manual').length },
  { id: 'rejected', label: 'Rejected', count: applications.value.filter(a => getReviewCategory(a) === 'rejected').length },
  { id: 'approved', label: 'Approved', count: applications.value.filter(a => getReviewCategory(a) === 'approved').length },
])
const filtered = computed(() => applications.value.filter(a => getReviewCategory(a) === activeReviewTab.value))
const emptyMessage = computed(() => ({ ocr: 'No OCR-verified supplier applications are awaiting approval.', manual: 'No supplier applications need manual review.', rejected: 'No rejected supplier applications.', approved: 'No approved suppliers yet.' })[activeReviewTab.value])
const selectedDocumentStatus = kind => application.value?.documents?.[kind]?.ocr?.status?.replaceAll('_', ' ') || (application.value?.documents?.[kind] ? 'Uploaded' : kind === 'distribution' ? 'Optional' : 'Missing')
const selectedDocumentStatusClass = kind => `status-${application.value?.documents?.[kind]?.ocr?.status || (application.value?.documents?.[kind] ? 'uploaded' : 'missing')}`
const handleLocationSelection = ({ lat, lng, address }) => { form.value.businessAddressLat = String(lat || ''); form.value.businessAddressLng = String(lng || ''); form.value.businessAddress = String(address || '').trim(); locationError.value = '' }
const api = async (path, body) => { const token = await auth.currentUser.getIdToken(); const response = await fetch(OTP_API_BASE + path, { method: body ? 'POST' : 'GET', headers: { Authorization: `Bearer ${token}`, 'content-type': 'application/json' }, body: body ? JSON.stringify(body) : undefined }); const result = await response.json(); if (!response.ok || !result.success) throw new Error(result.error || 'Unable to complete request.'); return result.data }
const load = trackPageLoad(async () => { error.value = ''; try { if (props.reviewer) applications.value = await api('/admin/supplier-verification'); else { application.value = await api('/supplier-verification/me'); form.value = Object.fromEntries([...fields.map(field => [field.key, application.value[field.key] || (field.key === 'contactEmail' ? auth.currentUser.email : '')]), ['businessAddress', application.value.businessAddress || ''], ['businessAddressLat', application.value.businessAddressLat || ''], ['businessAddressLng', application.value.businessAddressLng || '']]) } } catch (e) { error.value = e.message } })
const upload = async (kind, event) => { const file = event.target.files?.[0]; if (!file) return; selectedDocumentKind.value = kind; if (file.size > 10 * 1024 * 1024) { toast.error('Choose a file up to 10 MB.'); event.target.value = ''; return } busy.value = true; try { const base64 = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(',')[1]); reader.onerror = reject; reader.readAsDataURL(file) }); const document = await api('/supplier-verification/documents', { kind, name: file.name, base64, businessName: form.value.businessName, representativeName: form.value.representativeName }); application.value.documents = { ...application.value.documents, [kind]: document }; const extracted = document.ocr?.extractedFields || {}; if (extracted.registrationNumber) form.value.registrationNumber = extracted.registrationNumber; if (extracted.taxNumber) form.value.taxNumber = extracted.taxNumber; toast.success(document.ocr?.status === 'verified' ? 'Document uploaded and OCR checks passed.' : 'Document uploaded. Review the OCR result before submitting.') } catch (e) { toast.error(e.message) } finally { busy.value = false; event.target.value = '' } }
const submit = async () => { busy.value = true; try { await api('/supplier-verification/submit', form.value); await load(); toast.success('Application submitted for review.') } catch (e) { error.value = e.message } finally { busy.value = false } }
const review = async (a, action) => { busy.value = true; try { await api(`/admin/supplier-verification/${encodeURIComponent(a.id)}/review`, { action, reason: reasons.value[a.id] || '' }); await load(); if (histories.value[a.id]) await loadHistory(a.id); toast.success('Review decision saved.') } catch (e) { toast.error(e.message) } finally { busy.value = false } }
const openDocument = async (id, kind) => { try { documentUrl.value = (await api(`/supplier-verification/${encodeURIComponent(id)}/documents/${encodeURIComponent(kind)}`)).url } catch (e) { toast.error(e.message) } }
const loadHistory = async id => { try { histories.value[id] = await api(`/admin/supplier-verification/${encodeURIComponent(id)}/history`) } catch (e) { toast.error(e.message) } }
onMounted(load)
</script>
<style scoped>
